/** A recipe for the cooking game from what goes in, its decoys, and how it is cooked. */
function rec(d: FoodId, title: string, items: Ingredient[], decoys: Ingredient[], how: 'heat' | 'mix' | 'chop' | 'flip', order?: Ingredient[]): StallInfo['recipe'] {
  const steps: Step[] = [{ kind: 'pick', title, hint: 'Pick what goes into it. Some of these do not belong.', items, decoys }];
  if (how === 'heat') steps.push({ kind: 'heat', title: 'On the heat', hint: 'Stop the needle in the zone. Not raw, not burnt.', rounds: 3, speed: 1.2, label: 'Perfect' });
  if (how === 'mix') steps.push({ kind: 'mix', title: 'Stir it through', hint: 'Draw circles, smooth and steady.', rounds: 6 });
  if (how === 'chop') steps.push({ kind: 'chop', title: 'Prep', hint: 'Tap as the blade passes each piece.', rounds: 4, speed: 1.2 });
  if (how === 'flip') steps.push({ kind: 'heat', title: 'Sear and flip', hint: 'Flip each one in the zone.', rounds: 3, speed: 1.4, label: 'Seared' });
  if (order) steps.push({ kind: 'order', title: 'Build it', hint: 'In the right order.', items: order });
  return { dish: d, steps };
}

